def parse_duration(s):
    import re
    match = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if not match:
        return 0
    h, m, sec = match.groups()
    return int(h or 0) * 3600 + int(m or 0) * 60 + int(sec or 0)
